BIRD_2_2_GREEN.source:
/// A 2/2 green Bird creature token with "Whenever a land you control enters, this token gets +1/+0 until end of turn."
/// (CR 111). Call the Mountain Chocobo, Chocobo Racetrack and Gysahl Greens create this exact token.
pub static BIRD_2_2_GREEN: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Creature]),
    colors: Some(ColorSet(16)),
    power: Some(2),
    toughness: Some(2),
    abilities: &[
        triggered(
            when_asked(EventMask::ZONE_CHANGE, bird_2_2_green_when_land_control_enters),
            bird_2_2_green_token_gets_1_0,
            "Whenever a land you control enters, this token gets +1/+0 until end of turn.",
        ),
    ],
    ..token!(Bird)
};

/// "Whenever a land you control enters, this token gets +1/+0 until end of turn." (CR 608.2, 611.2a).
fn bird_2_2_green_token_gets_1_0(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> {
    let objects_0 = {
        let q: &dyn Query = g;
        Some(item.object)
            .into_iter()
            .filter(|&o| q.state().obj(o).became.is_none())
            .collect::<Vec<ObjectId>>()
    };
    instruction(
        g,
        |g| {
            for &object in &objects_0 {
                g.add_effect(
                    item.object,
                    object,
                    EffectKind::Pump(1, 0),
                    Duration::EndOfTurn,
                );
            }
        },
    );
    Ok(())
}

/// "Whenever a land you control enters" (CR 603.2).
fn bird_2_2_green_when_land_control_enters(
    q: &dyn Query,
    asker: &Asker,
    event: &Event,
) -> Option<Fired> {
    let Event::ZoneChange { new, to, .. } = event else { return None };
    let id = *new;
    let subject = Target::Object(id);
    if to.is(ZoneKind::Battlefield)
        && (q.chars(id).is(CardType::Land) && asker.controller == q.controller(id))
    {
        return Fired::about(subject);
    }
    None
}

