DEVIL.source:
/// A 1/1 red Devil creature token with "When this token dies, it deals 1 damage to any target." (CR 111). Dance with
/// Devils, Devils' Playground and Maestros Diabolist create this exact token.
pub static DEVIL: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Creature]),
    colors: Some(ColorSet(8)),
    power: Some(1),
    toughness: Some(1),
    abilities: &[
        triggered(
                when_asked(EventMask::ZONE_CHANGE, devil_when_token_dies),
                devil_deals_1_damage_any_target,
                "When this token dies, it deals 1 damage to any target.",
            )
            .targets(&[crate::targets::ANY]),
    ],
    ..token!(Devil)
};

/// "When this token dies, it deals 1 damage to any target." (CR 608.2, 120.3).
fn devil_deals_1_damage_any_target(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> {
    devil_token_1_announced(g, item, 0, false);
    let t_0 = devil_token_1_announced(g, item, 0, true);
    let source_0 = item.subject.object();
    let recipients_0 = t_0.clone();
    if let Some(source) = source_0 {
        let batch: Vec<(ObjectId, Target, u16)> = recipients_0
            .iter()
            .map(|t| (source, *t, 1u16))
            .collect();
        g.damage_together(&batch);
    }
    Ok(())
}

/// "When this token dies, it deals 1 damage to any target." (CR 608.2).
fn devil_token_1_announced(
    g: &dyn Game,
    item: &StackItem,
    spec: u8,
    legal: bool,
) -> Vec<Target> {
    (0..g.state().targets(item).len())
        .filter(|&i| {
            g.state().spec(item, i) == spec && (!legal || g.target_legal(item, i))
        })
        .map(|i| g.state().target(item, i))
        .collect()
}

/// "When this token dies" (CR 603.2).
fn devil_when_token_dies(_: &dyn Query, asker: &Asker, event: &Event) -> Option<Fired> {
    let Event::ZoneChange { old, from, to, .. } = event else { return None };
    let id = *old;
    let subject = Target::Object(id);
    if to.is(ZoneKind::Graveyard) && from.is(ZoneKind::Battlefield) && asker.source == id
    {
        return Fired::about(subject);
    }
    None
}

