/// "Return target nonland permanent to its owner's hand. If it was attacking, create a 1/1 colorless Drone artifact
/// creature token with flying and "This token can block only creatures with flying."" (CR 604.1).
fn drone_return_target_nonland_permanent_owners_rule(
    q: &dyn Query,
    source: ObjectId,
    blocker: ObjectId,
    attacker: ObjectId,
) -> bool {
    let asker = &Asker::new(source, q.controller(source));
    !(blocker == asker.source
        && !((q.chars(attacker).is(CardType::Creature)
            && q.chars(attacker).keywords.has(Keyword::Flying))))
}

