            },
            "Sacrifice this token: Add {C}.",
        ),
    ],
    ..token!(Eldrazi Spawn)
};

/// "Sacrifice this token: Add {C}." (CR 605.3a, 106.3).
fn eldrazi_spawn_add_c_mana(g: &mut dyn Game, asker: &Asker, _: Option<Color>) -> Result<(), Suspend> {
    g.add_mana(asker.controller, Mana::C, 1);
    Ok(())
}

