/// A 0/0 green and white Elemental creature token with "This token's power and toughness are each equal to the number
/// of creatures you control." (CR 111). Vernal Sovereign and Voice of Resurgence create this exact token.
pub static ELEMENTAL_0_0_GREEN_WHITE: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Creature]),
    colors: Some(ColorSet(17)),
    power: Some(0),
    toughness: Some(0),
    statics: &[
        characteristic_defining(
            Layer::PtDefine,
            elemental_0_0_green_white_create_green_white_elemental_creature_apply_0,
            "This token's power and toughness are each equal to the number of creatures you control.",
        ),
    ],
    ..token!(Elemental)
};

/// "Whenever this creature enters or attacks, create a green and white Elemental creature token with "This token's
/// power and toughness are each equal to the number of creatures you control."" (CR 604.1).
fn elemental_0_0_green_white_create_green_white_elemental_creature_apply_0(
    q: &dyn LayerQuery,
    source: ObjectId,
    chars: &mut Chars,
) {
    let asker = &Asker::new(source, q.controller(source));
    let (p, t) = (
        (q
            .state()
            .battlefield()
            .iter()
            .copied()
            .filter(|&id| {
                q.chars(id).is(CardType::Creature)
                    && asker.controller == q.controller(id)
            })
            .collect::<Vec<ObjectId>>()
            .len() as i64) as i16,
        (q
            .state()
            .battlefield()
            .iter()
            .copied()
            .filter(|&id| {
                q.chars(id).is(CardType::Creature)
                    && asker.controller == q.controller(id)
            })
            .collect::<Vec<ObjectId>>()
            .len() as i64) as i16,
    );
    chars.power = Some(p);
    chars.toughness = Some(t);
}

