/// "Return all creatures to their owners' hands. For each opponent who controlled a creature returned this way, you
/// create two 1/1 blue Faerie creature tokens with flying and "This token can block only creatures with flying."" (CR
/// 604.1).
fn faerie_1_1_blue_return_all_creatures_their_owners_rule(
    q: &dyn Query,
    source: ObjectId,
    blocker: ObjectId,
    attacker: ObjectId,
) -> bool {
    let asker = &Asker::new(source, q.controller(source));
    !(blocker == asker.source
        && !((q.chars(attacker).is(CardType::Creature)
            && q.chars(attacker).keywords.has(Keyword::Flying))))
}

