JUNK.source:
/// A colorless Junk artifact token with "{T}, Sacrifice this token: Exile the top card of your library. You may play
/// that card this turn. Activate only as a sorcery." (CR 111). Boomer Scrapper, Break Down and Commander Sofia Daguerre
/// create this exact token.
pub static JUNK: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Artifact]),
    abilities: &[
        ability(
                SACRIFICE_THIS.and(TAP),
                junk_exile_top_card_library_play,
                "{T}, Sacrifice this token: Exile the top card of your library. You may play that card this turn. Activate only as a sorcery.",
            )
            .sorcery_speed(),
    ],
    ..token!(Junk)
};

/// "{T}, Sacrifice this token: Exile the top card of your library. You may play that card this turn. Activate only as a
/// sorcery." (CR 608.2, 406.3).
fn junk_exile_top_card_library_play(
    g: &mut dyn Game,
    item: &StackItem,
) -> Result<(), Suspend> {
    let objects_0 = {
        let q: &dyn Query = g;
        Some(item.controller)
            .into_iter()
            .flat_map(|p: PlayerId| q.state().zone(Zone::library(p)).to_vec())
            .collect::<Vec<ObjectId>>()
            .into_iter()
            .take(1)
            .collect::<Vec<ObjectId>>()
    };
    let moved_0 = g.exile_all(&objects_0);
    g.end_sentence();
    let cards_1_0 = moved_0
        .clone()
        .get(0)
        .copied()
        .into_iter()
        .collect::<Vec<ObjectId>>();
    let players_1_0 = Some(item.controller).into_iter().collect::<Vec<PlayerId>>();
    instruction(
        g,
        |g| {
            for &card in &cards_1_0 {
                if g.obj(card).zone.is(ZoneKind::Exile) {
                    for &player in &players_1_0 {
                        g.allow_play(
                            card,
                            player,
                            PlayGrant {
                                lands: true,
                                expiry: Expiry::EndOfTurn,
                                ..PlayGrant::CAST
                            },
                        );
                    }
                }
            }
        },
    );
    Ok(())
}

