MERCENARY.source:
/// A 1/1 red Mercenary creature token with "{T}: Target creature you control gets +1/+0 until end of turn. Activate
/// only as a sorcery." (CR 111). Angelic Sell-Sword, At Knifepoint and Brimstone Roundup create this exact token.
pub static MERCENARY: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Creature]),
    colors: Some(ColorSet(8)),
    power: Some(1),
    toughness: Some(1),
    abilities: &[
        ability(
                TAP,
                mercenary_target_creature_control_gets_1,
                "{T}: Target creature you control gets +1/+0 until end of turn. Activate only as a sorcery.",
            )
            .targets(&[target(mercenary_target_creature_control_gets_1_target_0)])
            .sorcery_speed(),
    ],
    ..token!(Mercenary)
};

/// "{T}: Target creature you control gets +1/+0 until end of turn. Activate only as a sorcery." (CR 608.2, 611.2a).
fn mercenary_target_creature_control_gets_1(
    g: &mut dyn Game,
    item: &StackItem,
) -> Result<(), Suspend> {
    let t_0_raw = mercenary_token_1_announced(g, item, 0, false);
    let t_0 = mercenary_token_1_announced(g, item, 0, true);
    let objects_0 = {
        let q: &dyn Query = g;
        t_0_raw
            .get(0)
            .copied()
            .filter(|t| t_0.contains(t))
            .and_then(|t: Target| t.object())
            .into_iter()
            .filter(|&o| q.state().obj(o).became.is_none())
            .collect::<Vec<ObjectId>>()
    };
    instruction(
        g,
        |g| {
            for &object in &objects_0 {
                g.add_effect(
                    item.object,
                    object,
                    EffectKind::Pump(1, 0),
                    Duration::EndOfTurn,
                );
            }
        },
    );
    Ok(())
}

/// "{T}: Target creature you control gets +1/+0 until end of turn. Activate only as a sorcery." (CR 115.1).
fn mercenary_target_creature_control_gets_1_target_0(
    q: &dyn Query,
    asker: &Asker,
    t: Target,
) -> bool {
    matches!(
        t, Target::Object(id) if crate::targets::permanent(q, id) && ((q
        .chars(id).is(CardType::Creature) && asker.controller == q.controller(id)))
    )
}

/// "{T}: Target creature you control gets +1/+0 until end of turn. Activate only as a sorcery." (CR 608.2).
fn mercenary_token_1_announced(
    g: &dyn Game,
    item: &StackItem,
    spec: u8,
    legal: bool,
) -> Vec<Target> {
    (0..g.state().targets(item).len())
        .filter(|&i| {
            g.state().spec(item, i) == spec && (!legal || g.target_legal(item, i))
        })
        .map(|i| g.state().target(item, i))
        .collect()
}

