SKELETON_1_1_BLACK.source:
/// A 1/1 black Skeleton creature token with "{B}: Regenerate this token." (CR 111). Drudge Spell and Skeletonize create
/// this exact token.
pub static SKELETON_1_1_BLACK: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Creature]),
    colors: Some(ColorSet(4)),
    power: Some(1),
    toughness: Some(1),
    abilities: &[ability(cost("{B}"), skeleton_1_1_black_regenerate_token, "{B}: Regenerate this token.")],
    ..token!(Skeleton)
};

/// "{B}: Regenerate this token." (CR 608.2, 611.2a).
fn skeleton_1_1_black_regenerate_token(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> {
    let objects_0 = {
        let q: &dyn Query = g;
        Some(item.object)
            .into_iter()
            .filter(|&o| q.state().obj(o).became.is_none())
            .collect::<Vec<ObjectId>>()
    };
    instruction(
        g,
        |g| {
            for object in objects_0 {
                g.add_effect(
                    item.object,
                    object,
                    EffectKind::RegenerationShield,
                    Duration::EndOfTurn,
                );
            }
        },
    );
    Ok(())
}

