WIZARD.source:
/// A 0/1 black Wizard creature token with "Whenever you cast a noncreature spell, this token deals 1 damage to each
/// opponent." (CR 111). Circle of Power, Mysidian Elder and Queen Brahne create this exact token.
pub static WIZARD: CardDef = CardDef {
    types: TypeSet::of(&[CardType::Creature]),
    colors: Some(ColorSet(4)),
    power: Some(0),
    toughness: Some(1),
    abilities: &[
        triggered(
            when_asked(EventMask::SPELL_CAST, wizard_when_cast_noncreature_spell),
            wizard_token_deals_1_damage_opponent,
            "Whenever you cast a noncreature spell, this token deals 1 damage to each opponent.",
        ),
    ],
    ..token!(Wizard)
};

/// "Whenever you cast a noncreature spell, this token deals 1 damage to each opponent." (CR 608.2, 120.3).
fn wizard_token_deals_1_damage_opponent(
    g: &mut dyn Game,
    item: &StackItem,
) -> Result<(), Suspend> {
    let recipients_0 = {
        let q: &dyn Query = g;
        q.state()
            .opponents(item.controller)
            .collect::<Vec<PlayerId>>()
            .into_iter()
            .map(Target::Player)
            .collect::<Vec<Target>>()
    };
    let batch: Vec<(ObjectId, Target, u16)> = recipients_0
        .iter()
        .map(|t| (item.object, *t, 1u16))
        .collect();
    g.damage_together(&batch);
    Ok(())
}

/// "Whenever you cast a noncreature spell" (CR 603.2).
fn wizard_when_cast_noncreature_spell(
    q: &dyn Query,
    asker: &Asker,
    event: &Event,
) -> Option<Fired> {
    let Event::SpellCast { spell, player, .. } = event else { return None };
    let id = *spell;
    let subject = Target::Object(id);
    if asker.controller == *player && !(q.chars(id).is(CardType::Creature)) {
        return Fired::about(subject);
    }
    None
}

